import{c as a,Q as r,j as t,m as i}from"./chunks/framework.BXc4yaFE.js";const u=JSON.parse('{"title":"HyMem: Hybrid Memory Architecture with Dynamic Retrieval Scheduling","description":"","frontmatter":{"url":"https://arxiv.org/abs/2602.13933","title":"HyMem: Hybrid Memory Architecture with Dynamic Retrieval Scheduling","archived_date":"2026-06-24T00:00:00.000Z","arxiv_id":2602.13933,"authors":["Xiaochen Zhao","Kaikai Wang","Xiaowen Zhang","Chen Yao","Aili Wang"],"domains":["cs.AI"],"html":"https://arxiv.org/html/2602.13933v1","pdf_path":"pdfs/2602.13933.pdf","published_date":"2026-02-15T00:00:00.000Z"},"headers":[],"relativePath":"research/papers/2026-02-15-hymem-hybrid-memory-dynamic-retrieval-2602-13933.md","filePath":"research/papers/2026-02-15-hymem-hybrid-memory-dynamic-retrieval-2602-13933.md","lastUpdated":1785909234000}'),o={name:"research/papers/2026-02-15-hymem-hybrid-memory-dynamic-retrieval-2602-13933.md"};function n(l,e,s,c,m,h){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="hymem-hybrid-memory-architecture-with-dynamic-retrieval-scheduling" tabindex="-1">HyMem: Hybrid Memory Architecture with Dynamic Retrieval Scheduling <a class="header-anchor" href="#hymem-hybrid-memory-architecture-with-dynamic-retrieval-scheduling" aria-label="Permalink to &quot;HyMem: Hybrid Memory Architecture with Dynamic Retrieval Scheduling&quot;">​</a></h1><p><strong>Authors</strong>: Xiaochen Zhao, Kaikai Wang, Xiaowen Zhang, Chen Yao, Aili Wang <strong>Published</strong>: February 15, 2026 <strong>Source</strong>: <a href="https://arxiv.org/abs/2602.13933" target="_blank" rel="noreferrer">https://arxiv.org/abs/2602.13933</a> · <a href="https://arxiv.org/html/2602.13933v1" target="_blank" rel="noreferrer">HTML</a><strong>arXiv ID</strong>: 2602.13933 <strong>Categories</strong>: cs.AI <strong>PDF</strong>: <a href="https://arxiv.org/abs/2602.13933" target="_blank" rel="noreferrer">research/papers/pdfs/2602.13933.pdf</a> (18 pp, full text archived)</p><hr><h2 id="abstract-quoted" tabindex="-1">Abstract (quoted) <a class="header-anchor" href="#abstract-quoted" aria-label="Permalink to &quot;Abstract (quoted)&quot;">​</a></h2><blockquote><p>Large language model (LLM) agents demonstrate strong performance in short-text contexts but often underperform in extended dialogues due to inefficient memory management. Existing approaches face a fundamental trade-off between efficiency and effectiveness: memory compression risks losing critical details required for complex reasoning, while retaining raw text introduces unnecessary computational overhead for simple queries. The crux lies in the limitations of monolithic memory representations and static retrieval mechanisms, which fail to emulate the flexible and proactive memory scheduling capabilities observed in humans, thus struggling to adapt to diverse problem scenarios. Inspired by the principle of cognitive economy, we propose HyMem, a hybrid memory architecture that enables dynamic on-demand scheduling through multi-granular memory representations. HyMem adopts a dual-granular storage scheme paired with a dynamic two-tier retrieval system: a lightweight module constructs summary-level context for efficient response generation, while an LLM-based deep module is selectively activated only for complex queries, augmented by a reflection mechanism for iterative reasoning refinement. Experiments show that HyMem achieves strong performance on both the LOCOMO and LongMemEval benchmarks, outperforming full-context while reducing computational cost by 92.6%, establishing a state-of-the-art balance between efficiency and performance in long-term memory management.</p></blockquote><hr><h2 id="結構化摘要" tabindex="-1">結構化摘要 <a class="header-anchor" href="#結構化摘要" aria-label="Permalink to &quot;結構化摘要&quot;">​</a></h2><h3 id="核心貢獻" tabindex="-1">核心貢獻 <a class="header-anchor" href="#核心貢獻" aria-label="Permalink to &quot;核心貢獻&quot;">​</a></h3><ul><li>提出 HyMem：受 cognitive economy 啟發的 hybrid memory 架構，透過 multi-granular 記憶表徵實現 dynamic on-demand scheduling。</li><li>dual-granular storage + dynamic two-tier retrieval：lightweight 模組建構 summary-level context 供高效生成；LLM-based deep 模組僅在 complex query 時選擇性啟動，並以 reflection 機制做 iterative reasoning refinement。</li></ul><h3 id="關鍵結果" tabindex="-1">關鍵結果 <a class="header-anchor" href="#關鍵結果" aria-label="Permalink to &quot;關鍵結果&quot;">​</a></h3><ul><li>於 LOCOMO 與 LongMemEval 表現強勁，outperform full-context 同時降低計算成本 92.6%。</li><li>在效率與效能間建立 SOTA 平衡。</li></ul><h3 id="限制" tabindex="-1">限制 <a class="header-anchor" href="#限制" aria-label="Permalink to &quot;限制&quot;">​</a></h3><ul><li>文件未於 abstract 列明確 limitation；判斷弱點：deep 模組「何時啟動」的 gating 準確度未在 abstract 量化，誤判將損及複雜查詢；92.6% 成本下降為相對 full-context，基準偏寬鬆。</li></ul><hr><h2 id="workspace-關聯-評估-非既成結論" tabindex="-1">Workspace 關聯（評估，非既成結論） <a class="header-anchor" href="#workspace-關聯-評估-非既成結論" aria-label="Permalink to &quot;Workspace 關聯（評估，非既成結論）&quot;">​</a></h2><ul><li>「lightweight 模組常駐 + deep 模組僅 complex query 啟動」精準對應 <code>core.md §PROPOSE 委派</code>（原 subagent-strategy.md）的委派決策與 multi-mode：簡單任務走 Haiku/inline，複雜才升 Sonnet/Opus，是 effort-first 紀律的記憶層映射。</li><li>「降低計算成本 92.6% 而不犧牲效能」呼應 context-management token budget 與 <code>pilot</code>（tier=cost，原 <code>haiku-pilot</code>） 成本紀律。</li><li>two-tier retrieval（粗→深）+ reflection 對應 core.md「判斷 vs 決定」分層與 RECORD 反思迴圈；⚠️ gating 誤判風險對應「unverified_success 閘門」——deep 模組未啟動時不得假設淺層結果完整。</li></ul>',16)])])}const g=a(o,[["render",n]]);export{u as __pageData,g as default};
